<?php namespace App\Controllers;
class Dashboard extends BaseController{
 public function index(){if($r=$this->mustLogin())return $r;$m=new \App\Models\MaterialModel();$db=db_connect();$month=$this->request->getGet('month')?:date('Y-m');$rows=$db->query("SELECT m.*,COALESCE(ms.opening_stock,0) opening_stock,ms.physical_stock_month_end,COALESCE(SUM(d.receipt_qty),0) receipts,COALESCE(SUM(d.issued_qty),0) issued,COALESCE(SUM(d.production_output_qty),0) production,COALESCE(SUM(d.in_process_rejection_qty+d.other_rejection_qty),0) rejection,COALESCE(SUM(d.transfer_out_qty),0) transfer,COALESCE(SUM(d.samples_qty),0) samples,(COALESCE(ms.opening_stock,0)+COALESCE(SUM(d.receipt_qty),0)-COALESCE(SUM(d.issued_qty),0)) closing_stock FROM materials m LEFT JOIN monthly_stock ms ON ms.material_id=m.id AND ms.month_key=? LEFT JOIN daily_entries d ON d.material_id=m.id AND d.month_key=? GROUP BY m.id,ms.id ORDER BY m.id",[$month,$month])->getResultArray();$tot=['receipts'=>0,'issued'=>0,'production'=>0,'rejection'=>0,'transfer'=>0,'samples'=>0];foreach($rows as $x)foreach($tot as $k=>$_)$tot[$k]+=floatval($x[$k]);return $this->render('dashboard/index',['pageTitle'=>'Dashboard','month'=>$month,'rows'=>$rows,'tot'=>$tot]);}}
